{"sql": "WITH test AS (
    SELECT '1, 2, 3' AS s
),
split AS (
    SELECT s, list_transform(string_split(s, ','), x -> CAST(TRIM(x) AS INTEGER)) AS topping_ids
    FROM test
)
SELECT s, topping_ids, value AS topping_id
FROM split, LATERAL UNNEST(topping_ids) AS value"}

